export function accountingMoney(value) { return (Number(value || 0) / 100).toLocaleString('es-PE', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
export function accountingToday() { const d=new Date(); return new Intl.DateTimeFormat('en-CA',{timeZone:'America/Lima',year:'numeric',month:'2-digit',day:'2-digit'}).format(d); }
export function accountingCSV(text) {
 text=String(text).replace(/^\uFEFF/,'');const delimiter=text.split(/\r?\n/)[0].includes(';')?';':',';const rows=[];let row=[],cell='',quoted=false;
 for(let i=0;i<text.length;i++){const ch=text[i];if(ch==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else if(!quoted&&cell!=='')throw Error('Comillas inválidas en CSV.');else quoted=!quoted;}else if(ch===delimiter&&!quoted){row.push(cell);cell='';}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v!==''))rows.push(row);row=[];cell='';}else cell+=ch;if(rows.length>10001)throw Error('Máximo 10000 filas por archivo.');}
 if(quoted)throw Error('CSV con comillas sin cerrar.');row.push(cell);if(row.some(v=>v!==''))rows.push(row);if(rows.length<2)throw Error('El CSV debe incluir encabezados y datos.');const headers=rows.shift().map(h=>h.trim());if(new Set(headers).size!==headers.length||headers.some(h=>!h||['__proto__','constructor','prototype'].includes(h)))throw Error('Encabezados inválidos.');return rows.map(r=>{if(r.length!==headers.length)throw Error('Número de columnas inconsistente.');const out={};headers.forEach((h,i)=>{out[h]=r[i].trim();});return out;});
}
export function accountingDraft() { return {date:accountingToday(),currency:'PEN',rate:'1',branchId:null,memo:'',document:'',sourceType:'manual',sourceId:'manual-'+Date.now()+'-'+Math.random().toString(36).slice(2),lines:[{account:'',debit:'0',credit:'0',cashFlow:''},{account:'',debit:'0',credit:'0',cashFlow:''}]}; }
