export function guideUrl(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)&&!u.username&&!u.password?u.href:''}catch(e){return ''}}
export function guideFragments(text,citations=[]){const chars=Array.from(text||''),result=[];const append=value=>{const re=/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g;let match,last=0;const plain=s=>s.replace(/\*\*/g,'').replace(/^#{1,6}\s*/gm,'');while((match=re.exec(value))){if(match.index>last)result.push({text:plain(value.slice(last,match.index))});const url=guideUrl(match[2]);result.push({text:plain(match[1]),...(url?{url,title:match[1]}:{})});last=re.lastIndex;}if(last<value.length)result.push({text:plain(value.slice(last))});};let cursor=0,index=0;for(const c of citations.slice().sort((a,b)=>a.start-b.start)){const url=guideUrl(c.url);if(!url||!Number.isInteger(c.start)||!Number.isInteger(c.end)||c.start<cursor||c.end<=c.start||c.end>chars.length)continue;if(c.start>cursor)append(chars.slice(cursor,c.start).join(''));const original=chars.slice(c.start,c.end).join('');result.push({text:/https?:|\[|【/.test(original)?' ['+(++index)+']':original.replace(/\*\*/g,''),url,title:c.title});cursor=c.end}if(cursor<chars.length)append(chars.slice(cursor).join(''));return result}
export function guideChunks(text,max=220){const clean=(text||'').replace(/\[([^\]]+)\]\(https?:\/\/[^)]+\)/g,'$1').replace(/https?:\/\/\S+/g,'').replace(/[*#]/g,'').replace(/\s+/g,' ').trim();const result=[];let rest=clean;while(rest){if(rest.length<=max){result.push(rest);break}const part=rest.slice(0,max);let cut=Math.max(part.lastIndexOf('. '),part.lastIndexOf('? '),part.lastIndexOf('! '));if(cut<max/3)cut=part.lastIndexOf(' ');if(cut<1)cut=max;else cut++;result.push(rest.slice(0,cut).trim());rest=rest.slice(cut).trim()}return result.filter(Boolean)}
export function guideVideos(sources=[]){return sources.filter(s=>{const url=guideUrl(s.url);if(!url)return false;const u=new URL(url);return (['youtube.com','www.youtube.com','m.youtube.com'].includes(u.hostname)&&u.pathname==='/watch'&&!!u.searchParams.get('v'))||u.hostname==='youtu.be'||(['vimeo.com','www.vimeo.com'].includes(u.hostname)&&/^\/\d+/.test(u.pathname))}).map(s=>({url:guideUrl(s.url),title:s.title||'Ver video'}))}

export function guideItems(text){return (text||'').replace(/\[([^\]]+)\]\(https?:\/\/[^)]+\)/g,'$1').replace(/https?:\/\/\S+|\[\d+\]|\*\*/g,'').replace(/(?:No se encontró|No hay)\s+(?:un\s+)?video[^.\n]*(?:\.|$)/gi,'').replace(/([^0-9])[.;]\s+(?=[A-ZÁÉÍÓÚÑ])/g,'$1\n').split(/\r?\n/).map(s=>s.replace(/^\s*(?:[-•*]|\d+[.)])\s*/,'').replace(/^(?:La|El|Esta|Este)\s+.+?\s+(?:cuenta con|está equipad[ao] con|dispone de|tiene)\s+/i,'').replace(/^(?:Incluye|Cuenta con|Dispone de|Su|Sus)\s+/i,'').trim().replace(/\.$/,'')).filter(Boolean)}



