export function isLaborService(product){if(product.EsServicioManoObra!==undefined&&product.EsServicioManoObra!==null)return Number(product.EsServicioManoObra)===1;return product.CodigoBarra==='MANODEOBRA'}
const amount=value=>Number.isFinite(Number(value))?Number(value):0;
export function laborSummary(products){const services=products.map((product,index)=>({product,index})).filter(row=>isLaborService(row.product)).sort((a,b)=>(Number(a.product.IdProducto)||a.index)-(Number(b.product.IdProducto)||b.index));const costs=products.filter(product=>!isLaborService(product)&&(product.EsManoDeObra===true||Number(product.EsManoDeObra)===1)).reduce((sum,product)=>sum+Math.round(amount(product.precio)*amount(product.cantidad)*100),0);let remaining=costs;let gross=0;const rows=services.map(({product,index})=>{const quantity=Math.max(0,amount(product.cantidad));const unit=product.precioBruta===undefined||product.precioBruta===null?amount(product.precio):amount(product.precioBruta);const cents=Math.max(0,Math.round(unit*quantity*100));gross+=cents;const deduction=Math.min(cents,Math.max(0,remaining));remaining-=deduction;return {index,unitGross:unit,unitNet:quantity?Number(((cents-deduction)/100/quantity).toFixed(5)):unit,net:(cents-deduction)/100}});return {gross:gross/100,net:Math.max(0,gross-costs)/100,costs:costs/100,overBudget:services.length>0&&costs>gross,rows}}



